    void sends_the_reference_and_amount_as_the_provider_expects() {
        provider.stubFor(
                WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                                .withBody("{\"status\":\"approved\"}")));

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        verify(postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withRequestBody(equalToJson(
                        "{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}")));
    }

    @Test
    void an_approved_answer_is_read_back_as_approved() {
        provider.stubFor(
                WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                                .withBody("{\"status\":\"approved\"}")));

        var outcome = gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_with_200_is_read_back_as_declined() {
        provider.stubFor(
                WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                                .withBody("{\"status\":\"declined\"}")));

        var outcome = gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_payment_outright_with_402_is_read_back_as_declined() {
        provider.stubFor(
                WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(402)));

        var outcome = gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_provider_error_surfaces_as_a_failure_instead_of_a_silent_decline() {
        provider.stubFor(
                WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(500)));

        assertThatThrownBy(() -> gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
}
